/**
 * How Double front-facing plum blossom (`yae-muko-ume`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/yae-muko-ume";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Five rounded lobes form the face of the plum. The rounded tips of a second row show between them. Thirty fine white stamens, each tipped with a dot, radiate from the small round heart.","ja":"五つの丸いふくらみで梅の花の正面を形作り、その間から二重目の丸い花びらの先をのぞかせます。小さな丸い中心から、先に点のある細い白いしべを三十本放射状に伸ばします。"};

export default construction;
export { construction, description };
